INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (73, 19, 'pool.ts: pool and category data (PORT-2)', 'work', 'done', NULL, '2026-10-11, app/client/src/engine/pool.ts, pool.test.ts, test/fixtures.ts; loadCategories checked equal to categories.load() on real data (throw-away script)', 'Pure typed access to `pool.json` and the category files, mirroring `app/server/categories.py` and `game.category_of`. See plan 19, "Files".

