INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (310, 53, 'UI: licence=replace queue, reasons in MediaPanel, start-page link', 'work', 'done', NULL, '2026-10-12, authoring/ui/src/lib/types.ts (LicenceRecord, LicenceVerdict, Question.licence, queues.licence_replace), lib/api.ts (licence filter, searchMedia all), review/Review.svelte (licence=replace queue: open while a slot is replace, all-provider search, empty-list summary), review/MediaPanel.svelte (replace reasons, licence/PD/restrictions info), home/Home.svelte (start-page link), plans/08-review-tool.md, AGENTS.md. Checked in headless Chrome: queue shows q-0021, q-1100, q-1194 with reasons; start page shows 3; nothing picked', 'UI side of plan 53 (PUB-3), on the server API from the previous task of this plan.

