INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (407, 61, 'D-80: competitive (timed) revised spec', 'work', 'done', NULL, '2026-10-12, plans/decisions.md (D-80)', 'Add a new entry to `plans/decisions.md` (next free number, D-80 unless taken by then) recording competitive (timed) as specced in plan 61 ("Spec to record"). Don''t edit old entries.

