INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (420, 65, 'Seen counters: decision entry and plan docs (D-28 superseded)', 'work', 'done', NULL, '2026-10-12, plans/decisions.md (D-82, D-28 marked), plans/02-question-pool.md, 03-game-flow.md, 04-ui-tv-display.md, 05-gamemaster-controls.md, 12-client-engine.md, 13-game-modes.md, 16-content-target.md', 'Plans first (AGENTS.md): write the decision and update the plan files before the code changes of plan 65.

